discoveryRules.discoveryTemplate:
{% if data|length > 0 %}
    {% set result = ({
    "modelName": data[0].deviceInfo.model,
    "vendorName": data[0].deviceInfo.vendor,
    "modelDesc": {
        "deviceTypeName": "cwl",
        "deviceType": { "docsisVersion": data[0].vci[-3:] if data[0].vci else None }
        }}) %}
    {{ result|tojson }}
{% endif %}
